package com.ruoyi.ai.controller;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.ruoyi.ai.service.AiConversationAuditService;import com.ruoyi.common.annotation.Log;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.enums.BusinessType;@RestController @RequestMapping("/ai/admin/audit")public class AiConversationAuditController{private final AiConversationAuditService service;public AiConversationAuditController(AiConversationAuditService s){service=s;}@PreAuthorize("@ss.hasPermi('ai:conversation:audit')")@Log(title="AI 会话审计列表",businessType=BusinessType.OTHER)@GetMapping public AjaxResult list(@RequestParam(required=false)Long userId,@RequestParam(required=false)Long conversationId,@RequestParam(required=false)Long modelId,@RequestParam(required=false)String status,@RequestParam(required=false)String title,@RequestParam(required=false)String beginTime,@RequestParam(required=false)String endTime){return AjaxResult.success(service.list(userId,conversationId,modelId,status,title,beginTime,endTime));}@PreAuthorize("@ss.hasPermi('ai:conversation:audit')")@Log(title="AI 会话审计查看",businessType=BusinessType.OTHER)@GetMapping("/{id}")public AjaxResult detail(@PathVariable Long id){return AjaxResult.success(service.detail(id));}}
